const fs=require('fs'),path=require('path');const C=require('./config'),R=require('./rules'),S=require('./store'),U=require('./ui');
async function messages(channel){const result=[];let before;while(true){const batch=await channel.messages.fetch({limit:100,...(before?{before}:{})});if(!batch.size)break;result.push(...batch.values());if(batch.size<100)break;before=batch.last().id;}return result;}
async function clear(channel){if(![C.CHANNELS.dress,C.CHANNELS.positions,C.CHANNELS.leave].includes(channel.id))throw Error('Bereinigung für diesen Kanal nicht freigegeben.');if(S.read().cleared[channel.id])return;const all=await messages(channel);const backup=path.join(S.DIR,'backups');fs.mkdirSync(backup,{recursive:true});fs.writeFileSync(path.join(backup,channel.id+'-'+Date.now()+'.json'),JSON.stringify(all.map(m=>m.toJSON()),null,2));for(const m of all)await m.delete();S.change(s=>s.cleared[channel.id]=new Date().toISOString());console.log('Kanal bereinigt: '+channel.name+' ('+all.length+' Nachrichten)');}
async function upsert(api,key,channel,payload){const signature='Liberty Justice Associates • '+key;payload={...payload,allowedMentions:{parse:[]}};payload.embeds.forEach(e=>e.setFooter({text:signature}));const saved=S.read().panels[key];let message=saved?await channel.messages.fetch(saved).catch(e=>{if(e.code===10008)return null;throw e;}):null;if(!message){const all=await messages(channel);const matches=all.filter(m=>m.author.id===api.client.user.id&&m.embeds.some(e=>e.footer?.text===signature));message=matches.shift();for(const old of matches)await old.delete();}if(message)await message.edit(payload);else message=await channel.send(payload);S.change(s=>s.panels[key]=message.id);return message;}
module.exports=async function bootstrap(api){const g=api.guild();await g.channels.fetch();await g.roles.fetch();if(g.members.cache.size<g.memberCount)await g.members.fetch();
 for(const id of [...C.HR,...C.RANKS.map(r=>r[0]),C.EMPLOYEE,C.FORMER])if(!g.roles.cache.has(id))throw Error('Erforderliche Rolle fehlt: '+id);
 const channels={};for(const [key,id]of Object.entries(C.CHANNELS)){const ch=await api.channel(id);if(!ch||ch.guildId!==C.GUILD||!ch.isTextBased())throw Error('Erforderlicher Textkanal fehlt: '+key);channels[key]=ch;}
 if(!S.read().rightsBackup){const snapshot={at:new Date().toISOString(),channels:Object.values(channels).map(ch=>({id:ch.id,name:ch.name,overwrites:ch.permissionOverwrites.cache.map(o=>({id:o.id,type:o.type,allow:o.allow.bitfield.toString(),deny:o.deny.bitfield.toString()}))})),categories:Object.values(C.QUEUES).map(id=>({id,name:g.channels.cache.get(id)?.name}))};fs.mkdirSync(S.DIR,{recursive:true});fs.writeFileSync(path.join(S.DIR,'rights-before.json'),JSON.stringify(snapshot,null,2));S.change(s=>s.rightsBackup=true);}
 for(const key of ['dress','positions','leave'])await clear(channels[key]);
 for(const key of ['management','updates','dress','positions','ads','leave','sanctions','orders'])await channels[key].permissionOverwrites.set(R.overwrites(g,api.client.user.id,{staff:key!=='management'&&key!=='sanctions'}),'Freigegebene Mitarbeiterverwaltung: Personalaktionen nur für Personalrollen; sonst Leserechte');
 await upsert(api,'Kleiderordnung',channels.dress,{embeds:[U.card('👔 Kleiderordnung','Die Kleidung soll stets gepflegt, professionell und in neutralen Farben gewählt werden.\n\nGerne können wir uns hierzu auch absprechen, wenn Ihr Unterstützung benötigt.')]});
 const positions=JSON.parse(fs.readFileSync(path.join(__dirname,'positions.json'),'utf8').replace(/^\uFEFF/,''));
 for(let start=0;start<positions.length;start+=3){const group=positions.slice(start,start+3);await upsert(api,'Rechte & Befugnisse '+(start/3+1),channels.positions,{embeds:group.map(p=>U.card(p.title,'**Rechte & Befugnisse nach Position**\n\n'+p.items.map(item=>'• '+item).join('\n')+(p.limits?'\n\n**🔒 Befugnisse & Einschränkungen**\n'+p.limits.map(item=>'• '+item).join('\n'):'')))});}
 for(const key of ['management','ads','leave','sanctions'])await upsert(api,'Personalpanel '+key,channels[key],U.panel(key));
 const employees=[...g.members.cache.values()].filter(R.employee);let renamed=0;
 for(const member of employees){await api.ensureEmployee(member,{seed:true});if(await api.prefix(member,true))renamed++;if(R.lawyer(member))await api.ensureLawyer(member);console.log('Personalakte eingerichtet: '+member.id);}
 const names={strafverteidigung:'🚨 UNZUGEORDNET · NOTFALL / VERTEIDIGUNG',klage:'🏛️ UNZUGEORDNET · AMTSHAFTUNG'};
 for(const [key,id]of Object.entries(C.QUEUES)){const category=g.channels.cache.get(id);if(category.name!==names[key])await category.setName(names[key],'Unzugeordnete Ticket-Warteschlange kennzeichnen');}
 for(const t of Object.values(api.deps.getTickets()).filter(t=>!t.closed)){const ch=await api.channel(t.channelId);if(!ch)continue;if(t.categoryKey==='bewerbung')await ch.permissionOverwrites.set(R.overwrites(g,api.client.user.id,{viewer:t.userId}),'Bewerbung nur Personalverwaltung und Bewerber');await api.deps.update(ch,t);}
 S.change(s=>{s.enabled=true;s.bootstrapAt=new Date().toISOString();s.seedCount=employees.length;});await api.updateOverview();
 if(!S.read().seedAnnounced){await channels.updates.send({embeds:[U.card('BESTANDSÜBERNAHME',`**${employees.length} bestehende Mitarbeiter** wurden in die Personalverwaltung übernommen.\nPersonalakten, Mitarbeiterbereiche und Anwaltsübersichten sind angelegt.\n**Namensabgleich möglich:** ${renamed}/${employees.length}.\nBestehende Rollen wurden nicht als Neueinstellungen ausgegeben.`)],allowedMentions:{parse:[]}});S.change(s=>s.seedAnnounced=true);}
 console.log(JSON.stringify({enabled:true,employees:employees.length,namesUpdated:renamed,lawyerForums:Object.keys(S.read().lawyers).length}));
};
module.exports.upsert=upsert;
